link.script:
const connection = new BareMux.BareMuxConnection("/baremux/worker.js");
(async () => {
  try {
    const wispUrl = (location.protocol === "https:" ? "wss" : "ws") + "://" + location.host + "/wisp/";
    await connection.setTransport("/epoxy/index.mjs", [{ wisp: wispUrl }]);
    console.log("✅ Bare-mux transport set successfully.");
  } catch (err) {
    console.error("❌ Failed to set bare-mux transport:", err);
  }
})();
if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/uv/sw.js");
  });
}

body.script:
const FIREBASE_CONFIG = {
    apiKey: "AIzaSyBVdkC6A13y8TDBQHefQFC-1Im0prEm70w",
    authDomain: "bonfire-chat-1ce06.firebaseapp.com",
    databaseURL: "https://bonfire-chat-1ce06-default-rtdb.firebaseio.com",
    projectId: "bonfire-chat-1ce06",
    storageBucket: "bonfire-chat-1ce06.firebasestorage.app",
    messagingSenderId: "192099688291",
    appId: "1:192099688291:web:a4e34459fbe0db4319bd56"
};
if (FIREBASE_CONFIG.apiKey && FIREBASE_CONFIG.databaseURL) {
    try {
        const { initializeApp } = await import("https://www.gstatic.com/firebasejs/10.7.1/firebase-app.js");
        const { getDatabase, ref, set, onValue } = await import("https://www.gstatic.com/firebasejs/10.7.1/firebase-database.js");
        const app = initializeApp(FIREBASE_CONFIG);
        const db = getDatabase(app);
        window.FIREBASE = { ref, set, onValue, db };
        window.dispatchEvent(new Event('firebase-ready'));
    } catch(e) { console.warn('Firebase init failed:', e); }
}

function uid() { return Math.random().toString(36).slice(2, 10); }
function now() { return Date.now(); }
function escapeHtml(s) { return String(s).replace(/[&<>"']/g, c => ({'&':'&','<':'<','>':'>','"':'"',"'":'''}[c])); }
function getBonfireUser() { try { const v = localStorage.getItem('bonfire_session'); return v ? JSON.parse(v) : null; } catch(e) { return null; } }
function timeAgo(ts) { const d = Date.now() - ts; if (d < 60000) return 'just now'; if (d < 3600000) return Math.floor(d/60000)+'m ago'; if (d < 86400000) return Math.floor(d/3600000)+'h ago'; return Math.floor(d/86400000)+'d ago'; }

function getMyNotifs() {
    const bu = getBonfireUser(); if (!bu) return [];
    try { const users = JSON.parse(localStorage.getItem('bonfire_users') || '{}'); return (users[bu] && users[bu].notifications) || []; } catch(e) { return []; }
}
function updateNotifUI() {
    const notifs = getMyNotifs();
    const unread = notifs.filter(n => !n.read).length;
    const badge = document.getElementById('notif-badge');
    if (badge) { if (unread > 0) { badge.textContent = unread > 99 ? '99+' : unread; badge.style.display = 'flex'; } else badge.style.display = 'none'; }
    const list = document.getElementById('notif-list');
    if (list) {
        if (!notifs.length) list.innerHTML = '
No notifications yet';
        else list.innerHTML = notifs.slice(0, 30).map(n => `

${n.icon || '🔔'}

${escapeHtml(n.title || '')}
${escapeHtml(n.body || '')}
${timeAgo(n.timestamp || Date.now())}`).join('');
    }
}
function toggleNotifPanel(ev) { if (ev) ev.stopPropagation(); const p = document.getElementById('notif-panel'); p.classList.toggle('active'); if (p.classList.contains('active')) updateNotifUI(); }
function markAllNotifsRead() { const bu = getBonfireUser(); if (!bu) return; try { const users = JSON.parse(localStorage.getItem('bonfire_users') || '{}'); if (!users[bu]) return; (users[bu].notifications || []).forEach(n => n.read = true); localStorage.setItem('bonfire_users', JSON.stringify(users)); if (window.BONFIRE && window.BONFIRE.syncUsers) window.BONFIRE.syncUsers(); updateNotifUI(); } catch(e) {} }
function showToast(title, body, icon, type) {
    const t = document.createElement('div'); t.className = 'notif-toast';
    t.innerHTML = `
${icon || '🔔'}

${escapeHtml(title || '')}
${escapeHtml(body || '')}`;
    document.body.appendChild(t);
    t.onclick = () => { t.remove(); toggleNotifPanel(); };
    setTimeout(() => { t.classList.add('removing'); setTimeout(() => t.remove(), 300); }, 5000);
}
window.showToast = showToast; window.updateNotifUI = updateNotifUI;

function tuxAlert(title, message, onClose) {
    const modal = document.getElementById('os-modal');
    document.getElementById('os-modal-title').innerText = title || 'Notice';
    document.getElementById('os-modal-desc').innerText = message || '';
    const input = document.getElementById('os-modal-input');
    const cancel = document.getElementById('os-modal-cancel');
    const confirm = document.getElementById('os-modal-confirm');
    if (input) input.style.display = 'none';
    cancel.style.display = 'none';
    cancel.onclick = null;
    confirm.innerText = 'OK';
    confirm.onclick = () => { modal.classList.remove('active'); if (onClose) onClose(); };
    modal.classList.add('active');
}
function tuxConfirm(title, message, onYes, onNo, yesLabel, noLabel) {
    const modal = document.getElementById('os-modal');
    document.getElementById('os-modal-title').innerText = title || 'Confirm';
    document.getElementById('os-modal-desc').innerText = message || '';
    const input = document.getElementById('os-modal-input');
    const cancel = document.getElementById('os-modal-cancel');
    const confirm = document.getElementById('os-modal-confirm');
    if (input) input.style.display = 'none';
    cancel.style.display = '';
    cancel.innerText = noLabel || 'Cancel';
    confirm.innerText = yesLabel || 'Confirm';
    const close = () => { modal.classList.remove('active'); cancel.onclick = null; confirm.onclick = null; };
    cancel.onclick = () => { close(); if (onNo) onNo(); };
    confirm.onclick = () => { close(); if (onYes) onYes(); };
    modal.classList.add('active');
}
function tuxPrompt(title, message, defaultValue, onOk, onCancel) {
    const modal = document.getElementById('os-modal');
    const input = document.getElementById('os-modal-input');
    document.getElementById('os-modal-title').innerText = title || 'Input';
    document.getElementById('os-modal-desc').innerText = message || '';
    input.style.display = '';
    input.value = defaultValue || '';
    const cancel = document.getElementById('os-modal-cancel');
    const confirm = document.getElementById('os-modal-confirm');
    cancel.style.display = '';
    cancel.innerText = 'Cancel';
    confirm.innerText = 'OK';
    const close = () => { modal.classList.remove('active'); input.style.display = 'none'; cancel.onclick = null; confirm.onclick = null; input.onkeydown = null; };
    cancel.onclick = () => { close(); if (onCancel) onCancel(); };
    confirm.onclick = () => { const v = input.value; close(); if (onOk) onOk(v); };
    input.onkeydown = (e) => { if (e.key === 'Enter') { const v = input.value; close(); if (onOk) onOk(v); } };
    modal.classList.add('active');
    setTimeout(() => input.focus(), 50);
}
function tuxConfirmDelete(title, message, onYes) {
    if (!toggles.confirmDelete) { onYes(); return; }
    tuxConfirm(title, message, onYes, null, 'Delete', 'Cancel');
}

document.addEventListener('click', e => {
    const p = document.getElementById('notif-panel');
    if (p && p.classList.contains('active') && !e.target.closest('.notif-panel') && !e.target.closest('.notif-bell')) p.classList.remove('active');
});

window.addEventListener('firebase-ready', () => {
    const bu = getBonfireUser(); if (!bu || !window.FIREBASE) return;
    const { ref, onValue, db } = window.FIREBASE;
    let initial = true;
    onValue(ref(db, 'bonfire/users/' + bu + '/notifications'), snap => {
        const list = snap.val() || [];
        const seenKey = 'tux_notif_seen_' + bu;
        const seen = JSON.parse(localStorage.getItem(seenKey) || '[]');
        const seenIds = new Set(seen);
        const newNotifs = list.filter(n => !seenIds.has(n.id) && !n.read);
        if (!initial) newNotifs.forEach(n => showToast(n.title, n.body, n.icon, n.type));
        localStorage.setItem(seenKey, JSON.stringify(list.map(n => n.id).slice(-100)));
        try { const users = JSON.parse(localStorage.getItem('bonfire_users') || '{}'); if (users[bu]) { users[bu].notifications = list; localStorage.setItem('bonfire_users', JSON.stringify(users)); } } catch(e) {}
        updateNotifUI(); initial = false;
    });
    onValue(ref(db, 'bonfire/users'), snap => { const d = snap.val(); if (!d) return; try { localStorage.setItem('bonfire_users', JSON.stringify(d)); } catch(e) {} updateNotifUI(); });
});

let calState = { year: new Date().getFullYear(), month: new Date().getMonth(), selected: new Date().toISOString().slice(0,10) };
function getCalEvents() { try { return JSON.parse(localStorage.getItem('tux_calendar_events')) || []; } catch(e) { return []; } }
function saveCalEvents(ev) { localStorage.setItem('tux_calendar_events', JSON.stringify(ev)); }
function calPrev() { calState.month--; if (calState.month < 0) { calState.month = 11; calState.year--; } renderCalendar(); }
function calNext() { calState.month++; if (calState.month > 11) { calState.month = 0; calState.year++; } renderCalendar(); }
function calToday() { const n = new Date(); calState.year = n.getFullYear(); calState.month = n.getMonth(); calState.selected = n.toISOString().slice(0,10); renderCalendar(); }
function calSelectDay(d) { calState.selected = d; renderCalendar(); }
function calAddEvent() { const tEl = document.getElementById('cal-event-title'); const tmEl = document.getElementById('cal-event-time'); const title = tEl.value.trim(); if (!title) return; const events = getCalEvents(); events.push({ id: uid(), date: calState.selected, time: tmEl.value, title }); saveCalEvents(events); tEl.value = ''; tmEl.value = ''; renderCalendar(); }
function calDeleteEvent(id) { tuxConfirmDelete('Delete Event', 'Delete this event?', () => { const events = getCalEvents().filter(e => e.id !== id); saveCalEvents(events); renderCalendar(); }); }
function renderCalendar() {
    const y = calState.year, m = calState.month;
    const first = new Date(y, m, 1); const startDay = first.getDay(); const daysInMonth = new Date(y, m+1, 0).getDate();
    const today = new Date().toISOString().slice(0,10); const events = getCalEvents();
    const grid = document.getElementById('cal-grid'); if (!grid) return;
    let html = '';
    ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(d => html += `
${d}`);
    for (let i = 0; i < startDay; i++) html += `
`;
    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
        const isToday = dateStr === today; const isSel = dateStr === calState.selected;
        const dayEvents = events.filter(e => e.date === dateStr);
        html += `
${d}${dayEvents.length ? `
${dayEvents.slice(0,3).map(() => '').join('')}` : ''}`;
    }
    grid.innerHTML = html;
    const monthEl = document.getElementById('cal-month'); if (monthEl) monthEl.innerText = first.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    const selEvents = events.filter(e => e.date === calState.selected).sort((a,b) => (a.time||'').localeCompare(b.time||''));
    const titleEl = document.getElementById('cal-events-title'); if (titleEl) titleEl.innerText = 'Events — ' + new Date(calState.selected + 'T00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});
    const listEl = document.getElementById('cal-events-list');
    if (listEl) listEl.innerHTML = selEvents.length ? selEvents.map(ev => `


${escapeHtml(ev.title)}${ev.time ? `
${escapeHtml(ev.time)}` : ''}×`).join('') : '
No events on this day';
}

const CHANGELOG_DATA = [
    { version:'v1.0', date:'November 8, 2026', items:[
        { tag:'new', text:'Initial public release of TUX OS' },
        { tag:'new', text:'Ultraviolet web proxy — browse any site through a service worker, with real backend fetch and rewrite' },
        { tag:'new', text:'Browser app with tabs, DuckDuckGo search, history, and 30+ tab cloaking options' },
        { tag:'new', text:'Games library across gn-math, now.gg, LuminSDK, and Seraph — includes Learn to Fly 1, 2, and 3' },
        { tag:'new', text:'Movies & Anime sources: TripleT HD, Cineby, Vumoo, FlixPlus, Movy, Aether, Plex Free, Bingebang, Fawesome, Filmzie, Ani.pm, HiAnimes, AniVault, Miruro, 9Anime, AnimeVillage, Az-AnimeX' },
        { tag:'new', text:'Bonfire chat with Firebase sync, servers, DMs, roles, custom emoji, and @everyone/@role/@user pings with a ping preference picker' },
        { tag:'new', text:'AI Hub with persistent chat history (Groq backend)' },
        { tag:'new', text:'Audius music player, Notes, Calculator, Clock with stopwatch, Calendar, and Changelog apps' },
        { tag:'new', text:'Three UI layouts: Default (OS), Classic (Windows-95 menu-driven shell), and Browser (Chrome-style tabs)' },
        { tag:'new', text:'Live clocks on the taskbar, desktop widget, and browser home page' },
        { tag:'new', text:'Theme engine with 19 built-in themes, custom color picker, wallpaper library, and custom uploads' },
        { tag:'new', text:'Privacy tools: tab cloaking, global text cloak, panic key, right-click and DevTools blocking' },
        { tag:'new', text:'Extensions panel: Ad Blocker, Dark Reader, autoplay blocking, cookie restrictions, fingerprint blocking, blocked counter' },
        { tag:'new', text:'TUX-style confirmation modals throughout — no more browser dialogs. Optional confirm-before-delete toggle.' },
        { tag:'new', text:'Lock screen with custom password, auto-lock timer, and first-run onboarding flow' }
    ]}
];

function renderChangelog() {
    const el = document.getElementById('cl-list'); if (!el) return;
    el.innerHTML = CHANGELOG_DATA.map(entry => `

${escapeHtml(entry.version)}
${escapeHtml(entry.date)}${entry.items.map(it => `
${it.tag}${escapeHtml(it.text)}`).join('')}`).join('');
}

let extensions = { adblock:true, darkreader:false, readfont:false, noautoplay:true, nocookies:false, nofingerprint:false };
try { const s = JSON.parse(localStorage.getItem('tux_ext')); if (s) extensions = { ...extensions, ...s }; } catch(e) {}
function saveExt() { localStorage.setItem('tux_ext', JSON.stringify(extensions)); }
function toggleExt(el, key) { extensions[key] = !extensions[key]; saveExt(); el.classList.toggle('on', extensions[key]); applyExtensions(); }
function initExt() {
    ['adblock','darkreader','readfont','noautoplay','nocookies','nofingerprint'].forEach(k => {
        const el = document.getElementById('toggle-ext-' + k);
        if (el) el.classList.toggle('on', extensions[k]);
    });
    applyExtensions();
    updateBlockedCount();
}
function getBlockedCount() { try { return parseInt(localStorage.getItem('tux_blocked_count')) || 0; } catch(e) { return 0; } }
function incrementBlocked() { localStorage.setItem('tux_blocked_count', getBlockedCount() + 1); updateBlockedCount(); }
function updateBlockedCount() { const el = document.getElementById('blocked-count'); if (el) el.textContent = getBlockedCount(); }
function resetBlockedCount() { localStorage.setItem('tux_blocked_count', '0'); updateBlockedCount(); }

const AD_DOMAINS = [
    'doubleclick.net','googlesyndication.com','googleadservices.com','googletagmanager.com',
    'googletagservices.com','google-analytics.com','adservice.google','pagead2.googlesyndication',
    'ads.pubmatic.com','ads.yahoo.com','adnxs.com','rubiconproject.com','pubmatic.com',
    'criteo.com','taboola.com','outbrain.com','quantserve.com','scorecardresearch.com',
    '2mdn.net','advertising.com','adroll.com','ads.yieldmo.com','bidswitch.net',
    'casalemedia.com','moatads.com','openx.net','advertising.apple','ads.tiktok.com',
    'analytics.tiktok.com','trc.taboola.com','ad.trafficjunky.net','popads.net',
    'popcash.net','propellerads.com','exoclick.com','juicyads.com','trafficjunky.com'
];
function isAdUrl(url) {
    if (!url) return false;
    const lower = url.toLowerCase();
    return AD_DOMAINS.some(d => lower.includes(d));
}
function applyExtensions() {
    document.querySelectorAll('iframe').forEach(f => {
        if (!f.src || f.src === 'about:blank' || f.src.startsWith('data:')) return;
        applyExtToIframe(f, f.src);
    });
    if (extensions.adblock) {
        document.querySelectorAll('[class*="banner"], [id*="ad-"], [class*="ad-slot"], [data-ad]').forEach(el => {
            if (el.closest('.window')) { el.style.display = 'none'; }
        });
    }
}
function applyExtToIframe(iframe, url) {
    if (extensions.adblock && isAdUrl(url)) {
        iframe.srcdoc = '
🛡️
Blocked by Ad Blocker
This URL matched the ad/tracker blocklist.';
        incrementBlocked();
        return;
    }
    const filters = [];
    if (extensions.darkreader) filters.push('invert(1) hue-rotate(180deg)');
    iframe.style.filter = filters.join(' ');
    if (extensions.noautoplay) {
        iframe.setAttribute('allow', 'clipboard-write; encrypted-media; fullscreen; picture-in-picture');
    } else {
        iframe.setAttribute('allow', 'autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture');
    }
    if (extensions.nocookies) {
        const cur = iframe.getAttribute('sandbox') || '';
        if (!cur.includes('allow-same-origin')) iframe.setAttribute('sandbox', (cur + ' allow-scripts allow-forms allow-popups').trim());
    }
}
document.addEventListener('load', e => {
    if (e.target.tagName === 'IFRAME' && e.target.src) applyExtToIframe(e.target, e.target.src);
}, true);

const _ifrObs = new MutationObserver(() => { if (typeof applyExtensions === 'function') applyExtensions(); });
setTimeout(() => _ifrObs.observe(document.body, { childList:true, subtree:true }), 500);

const BONFIRE = (() => {
    const STORE = { users:'bonfire_users', session:'bonfire_session', servers:'bonfire_servers', dms:'bonfire_dms', messages:'bonfire_messages', emojis:'bonfire_emojis' };
    const OWNER_USERNAME = 'almondjosh';
    const ROLES = {
        owner:{name:'Owner',color:'#ffd700',priority:100}, coowner:{name:'Co-Owner',color:'#b47bff',priority:80},
        moderator:{name:'Moderator',color:'#4ade80',priority:60}, helper:{name:'Helper',color:'#38bdf8',priority:40},
        member:{name:'Member',color:null,priority:10}
    };
    const PING_OPTIONS = [
        { id:'all', icon:'🔔', name:'All Pings', desc:'@everyone, role pings, personal mentions, links and updates.', prefs:{everyone:true,roles:true,personal:true,links:true,updates:true} },
        { id:'roles', icon:'🛡️', name:'Role & Personal Pings', desc:'Role pings and personal @mentions only.', prefs:{everyone:false,roles:true,personal:true,links:false,updates:false} },
        { id:'personal', icon:'💬', name:'Personal Pings Only', desc:'Only when someone @mentions you by name.', prefs:{everyone:false,roles:false,personal:true,links:false,updates:false} },
        { id:'links', icon:'🔗', name:'Link Pings', desc:'Only when someone posts a link.', prefs:{everyone:false,roles:false,personal:false,links:true,updates:false} },
        { id:'updates', icon:'📢', name:'Update Pings', desc:'Only announcements and updates.', prefs:{everyone:false,roles:false,personal:false,links:false,updates:true} },
        { id:'none', icon:'🔕', name:'No Pings', desc:'Mute everything. You can change this any time.', prefs:{everyone:false,roles:false,personal:false,links:false,updates:false} }
    ];
    const NORMAL_EMOJIS = ['😀','😂','🥲','😍','🥰','😎','🤔','😅','😤','🥺','😴','🤯','🙃','😇','🤗','🤫','🥳','😱','🙄','😬','😌','🫡','🤝','👍','👎','👏','🙌','🙏','✌️','🤞','💪','❤️','🧡','💛','💚','💙','💜','🖤','🤍','💔','💯','🔥','✨','🌟','⭐','💫','⚡','💥','🎉','🎊','🎈','🎁','🍕','🍔','🍟','🌮','🍩','☕','🍺','🍷','🎮','🎧','🎬','📷','💻','📱','🎨','✏️','📚','📖','💡','🔔','🚀','🌈','🌸','🌺','🌻','🍀','🌊','⛰️','🌙','☀️','🌎'];
    const bfUid = () => Math.random().toString(36).slice(2, 10);
    const bfNow = () => Date.now();
    const hash = s => { let h = 0; for (let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0; return h; };
    const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&','<':'<','>':'>','"':'"',"'":'''}[c]));

    let firebaseReady = false;
    function firebaseSet(key, val) {
        if (!firebaseReady || !window.FIREBASE) return;
        const { ref, set, db } = window.FIREBASE;
        const cleanKey = key.replace('bonfire_', '');
        try { set(ref(db, 'bonfire/' + cleanKey), val); } catch(e) {}
    }
    function firebaseLoadAll() {
        if (!firebaseReady || !window.FIREBASE) return;
        const { ref, onValue, db } = window.FIREBASE;
        onValue(ref(db, 'bonfire'), snap => {
            const data = snap.val(); if (!data) return;
            let changed = false;
            ['users','servers','dms','messages','emojis'].forEach(k => {
                if (data[k]) { const sk = 'bonfire_' + k; const local = localStorage.getItem(sk); const remote = JSON.stringify(data[k]); if (local !== remote) { localStorage.setItem(sk, remote); changed = true; } }
            });
            if (changed) { const s = JSON.parse(localStorage.getItem('bonfire_session') || 'null'); if (s) { state.me = s; render(); } }
            if (typeof window.updateNotifUI === 'function') window.updateNotifUI();
        });
    }
    window.addEventListener('firebase-ready', () => { firebaseReady = true; firebaseLoadAll(); });

    const load = (key, def) => { try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : def; } catch(e) { return def; } };
    const save = (key, val) => { localStorage.setItem(key, JSON.stringify(val)); firebaseSet(key, val); };

    let state = { me:null, activeServer:null, activeChannel:null, activeDM:null, view:'chat', profileTarget:null, modal:null, emojiPickerOpen:false, mentionPickerOpen:false, draft:'', refocusInput:false };

    const getUsers = () => load(STORE.users, {});
    const saveUsers = u => save(STORE.users, u);
    const getServers = () => load(STORE.servers, {});
    const saveServers = s => save(STORE.servers, s);
    const getDMs = () => load(STORE.dms, {});
    const saveDMs = d => save(STORE.dms, d);
    const getMessages = () => load(STORE.messages, {});
    const saveMessages = m => save(STORE.messages, m);
    const getEmojis = () => load(STORE.emojis, {});
    const saveEmojis = e => save(STORE.emojis, e);

    function findUserByUsername(u, usersObj) { const users = usersObj || getUsers(); const lower = u.toLowerCase(); for (const k in users) if (k.toLowerCase() === lower) return { username: k, data: users[k] }; return null; }

    function pushNotification(target, notif) {
        const users = getUsers(); if (!users[target]) return;
        users[target].notifications = users[target].notifications || [];
        users[target].notifications.unshift({ id: bfUid(), type: notif.type || 'system', icon: notif.icon || '🔔', title: notif.title || '', body: notif.body || '', timestamp: bfNow(), read: false });
        users[target].notifications = users[target].notifications.slice(0, 50);
        saveUsers(users);
    }

    function ensureOwnerServer(username) {
        const servers = getServers();
        let hq = null;
        for (const sid in servers) if (servers[sid].name === 'Bonfire HQ') { hq = servers[sid]; break; }
        if (!hq) {
            const sid = bfUid();
            hq = { id:sid, name:'Bonfire HQ', icon:'🔥', owner:OWNER_USERNAME, description:'The official Bonfire server. Welcome home.', members:{}, channels:[{id:'general',name:'general',type:'text'},{id:'announcements',name:'announcements',type:'text'},{id:'off-topic',name:'off-topic',type:'text'}], roles:[{id:'owner',name:'Owner',color:'#ffd700',priority:100},{id:'coowner',name:'Co-Owner',color:'#b47bff',priority:80},{id:'moderator',name:'Moderator',color:'#4ade80',priority:60},{id:'helper',name:'Helper',color:'#38bdf8',priority:40},{id:'member',name:'Member',color:null,priority:10}], roleRequests:[], customEmojis:[], createdAt:bfNow(), isPublic:true, isDefault:true };
            servers[sid] = hq;
        }
        if (!hq.members[username]) hq.members[username] = username.toLowerCase() === OWNER_USERNAME ? 'owner' : 'member';
        hq.members[OWNER_USERNAME] = 'owner';
        saveServers(servers);
    }

    function register(username, displayName, password) {
        if (!username || !displayName || !password) return { ok:false, error:'All fields required.' };
        if (!/^[a-z0-9_.]{3,20}$/i.test(username)) return { ok:false, error:'Username must be 3-20 chars.' };
        if (findUserByUsername(username)) return { ok:false, error:'That username is taken.' };
        const users = getUsers();
        users[username] = { displayName, passwordHash:hash(password), avatar:null, avatarEmoji:displayName[0]?.toUpperCase()||'?', accentColor:'#ff7a3d', banner:'linear-gradient(135deg,#ff7a3d,#ffb547)', bio:'New to Bonfire 🔥', pronouns:'', badge:'member', status:'online', friends:[], blocked:[], friendRequests:[], notifications:[], createdAt:bfNow() };
        saveUsers(users); ensureOwnerServer(username);
        return { ok:true };
    }
    function login(username, password) { const f = findUserByUsername(username); if (!f) return { ok:false, error:'No account.' }; if (f.data.passwordHash !== hash(password)) return { ok:false, error:'Wrong password.' }; return { ok:true, username:f.username }; }
    function getSession() { return load(STORE.session, null); }
    function setSession(u) { if (u) save(STORE.session, u); else localStorage.removeItem('bonfire_session'); }
    function getRoleFor(server, u) { const rid = server.members[u]; if (!rid) return null; return server.roles.find(r => r.id === rid) || { id:rid, name:rid, priority:10 }; }
    function canManageRoles(server, u) { const r = getRoleFor(server, u); return r && r.priority >= 60; }
    function canAddChannels(server, u) { const r = getRoleFor(server, u); return r && r.priority >= 40; }
    function canKickMembers(server, u) { const r = getRoleFor(server, u); return r && r.priority >= 60; }
    function isOwner(server, u) { return server.owner.toLowerCase() === u.toLowerCase(); }
    function getUserAvatar(u) { const users = getUsers(); const d = users[u]; if (!d) return { emoji:'?', color:'#ff7a3d', img:null }; return { emoji:d.avatarEmoji||'?', color:d.accentColor||'#ff7a3d', img:d.avatar }; }

    function formatContent(text) {
        let html = esc(text);
        const emojis = getEmojis();
        html = html.replace(/:([a-z0-9_]+):/gi, (m, name) => { const key = name.toLowerCase(); const found = Object.values(emojis).find(e => e.name.toLowerCase() === key); if (found) return ``; return m; });
        html = html.replace(/@([a-z0-9_.]+)/gi, (m, name) => {
            const low = name.toLowerCase();
            if (low === 'everyone' || low === 'here') return `${m}`;
            return `${m}`;
        });
        html = html.replace(/\n/g, '
');
        return html;
    }

    function render() {
        const root = document.getElementById('bonfire-root'); if (!root) return;
        if (!state.me) { root.innerHTML = renderGate(); return; }
        const meData = getUsers()[state.me];
        if (!meData) { state.me = null; setSession(null); root.innerHTML = renderGate(); return; }
        root.innerHTML = `
${renderRail()}${renderSidebar()}${renderMain()}${renderMembers()}${renderModal()}${renderEmojiPicker()}${renderMentionPicker()}`;
        requestAnimationFrame(() => {
            const m = document.getElementById('bf-messages'); if (m) m.scrollTop = m.scrollHeight;
            if (state.refocusInput) {
                const ta = document.getElementById('bf-message-input');
                if (ta) { ta.focus(); ta.selectionStart = ta.selectionEnd = ta.value.length; }
                state.refocusInput = false;
            }
        });
        if (typeof window.updateNotifUI === 'function') window.updateNotifUI();
    }

