    function gateTab(tab) { document.querySelectorAll('.bf-gate-tab').forEach(t => t.classList.toggle('active', t.dataset.gate === tab)); document.getElementById('gate-form-login').style.display = tab === 'login' ? 'block' : 'none'; document.getElementById('gate-form-register').style.display = tab === 'register' ? 'block' : 'none'; }

    function maybeShowPingSetup() {
        const u = getUsers()[state.me];
        if (u && !u.pingPrefs) { state.modal = { type:'pingSetup' }; return true; }
        return false;
    }

    function doLogin() {
        const u = document.getElementById('gate-login-user').value.trim();
        const p = document.getElementById('gate-login-pass').value;
        const r = login(u, p);
        if (!r.ok) { document.getElementById('gate-login-error').textContent = r.error; return; }
        state.me = r.username; setSession(r.username); ensureOwnerServer(r.username);
        const users = getUsers(); if (users[state.me]) users[state.me].status = 'online'; saveUsers(users);
        state.view = 'chat';
        const servers = getServers();
        const hq = Object.values(servers).find(s => s.name === 'Bonfire HQ' && s.members[state.me]);
        if (hq) { state.activeServer = hq.id; const ft = hq.channels.find(c => c.type === 'text'); state.activeChannel = ft?.id; }
        maybeShowPingSetup();
        if (typeof window.updateNotifUI === 'function') window.updateNotifUI();
        render();
    }
    function doRegister() {
        const u = document.getElementById('gate-reg-user').value.trim();
        const d = document.getElementById('gate-reg-display').value.trim();
        const p = document.getElementById('gate-reg-pass').value;
        const r = register(u, d, p);
        if (!r.ok) { document.getElementById('gate-reg-error').textContent = r.error; return; }
        state.me = u; setSession(u);
        state.view = 'chat';
        const servers = getServers();
        const hq = Object.values(servers).find(s => s.name === 'Bonfire HQ' && s.members[state.me]);
        if (hq) { state.activeServer = hq.id; const ft = hq.channels.find(c => c.type === 'text'); state.activeChannel = ft?.id; }
        maybeShowPingSetup();
        render();
    }
    function logout() { if (state.me) { const u = getUsers(); if (u[state.me]) u[state.me].status = 'offline'; saveUsers(u); } state.me = null; setSession(null); state.activeServer = null; state.activeChannel = null; state.view = 'chat'; state.modal = null; state.draft=''; render(); }
    function showFriends() { state.view = 'friends'; state.activeServer = null; state.activeChannel = null; state.draft=''; render(); }
    function showServerBrowser() { state.view = 'browse'; state.activeServer = null; state.activeChannel = null; state.draft=''; render(); }
    function joinServer(sid) { const servers = getServers(); if (!servers[sid]) return; if (!servers[sid].members[state.me]) { servers[sid].members[state.me] = 'member'; saveServers(servers); } state.activeServer = sid; state.view = 'chat'; const first = servers[sid].channels.find(c => c.type === 'text'); state.activeChannel = first?.id; render(); }
    function leaveServer(id) { const servers = getServers(); if (!servers[id]) return; if (servers[id].owner.toLowerCase() === state.me.toLowerCase()) { tuxAlert('Owner cannot leave', 'You are the owner of this server. Delete it instead.'); return; } tuxConfirmDelete('Leave Server', 'Leave this server?', () => { const s2 = getServers(); if (!s2[id]) return; delete s2[id].members[state.me]; saveServers(s2); if (state.activeServer === id) { state.activeServer = null; state.activeChannel = null; } closeModal(); render(); }); }
    function selectServer(id) { state.activeServer = id; state.view = 'chat'; state.draft=''; const server = getServers()[id]; if (server) { const ft = server.channels.find(c => c.type === 'text'); state.activeChannel = ft?.id; } render(); }
    function selectChannel(id) { state.activeChannel = id; state.view = 'chat'; state.activeDM = null; state.draft=''; render(); }
    function openDMWith(username) { if (!username) return; const dms = getDMs(); let found = null; for (const id in dms) if (dms[id].participants.includes(state.me) && dms[id].participants.includes(username)) { found = dms[id]; break; } if (!found) { const id = 'dm_' + bfUid(); found = { id, participants:[state.me, username], createdAt:bfNow() }; dms[id] = found; saveDMs(dms); } state.view = 'dm'; state.activeDM = found.id; state.activeServer = null; state.activeChannel = null; state.draft=''; render(); }
    function openCreateServer() { state.modal = { type:'createServer' }; render(); }
    function createServer() { const name = document.getElementById('new-server-name').value.trim(); const icon = document.getElementById('new-server-icon').value.trim() || '🔥'; const desc = document.getElementById('new-server-desc').value.trim(); if (!name) return; const sid = bfUid(); const servers = getServers(); servers[sid] = { id:sid, name, icon, owner:state.me, description:desc, members:{[state.me]:'owner'}, channels:[{id:'general',name:'general',type:'text'}], roles:[{id:'owner',name:'Owner',color:'#ffd700',priority:100},{id:'coowner',name:'Co-Owner',color:'#b47bff',priority:80},{id:'moderator',name:'Moderator',color:'#4ade80',priority:60},{id:'helper',name:'Helper',color:'#38bdf8',priority:40},{id:'member',name:'Member',color:null,priority:10}], roleRequests:[], customEmojis:[], createdAt:bfNow(), isPublic:true }; saveServers(servers); state.activeServer = sid; state.activeChannel = 'general'; state.view = 'chat'; state.modal = null; render(); }
    function showServerMenu(ev, id) { if (ev) ev.stopPropagation(); state.modal = { type:'serverMenu' }; render(); }
    function saveServerSettings() { const servers = getServers(); const server = servers[state.activeServer]; if (!server) return; if (!canManageRoles(server, state.me)) { tuxAlert('No permission', 'You do not have permission to change server settings.'); return; } server.name = document.getElementById('srv-name').value.trim() || server.name; server.description = document.getElementById('srv-desc').value.trim(); saveServers(servers); closeModal(); render(); }
    function deleteServer(id) { const servers = getServers(); if (!isOwner(servers[id], state.me)) { tuxAlert('Not allowed', 'Only the owner can delete this server.'); return; } tuxConfirmDelete('Delete Server', 'Delete this server permanently?', () => { const s2 = getServers(); delete s2[id]; saveServers(s2); state.activeServer = null; closeModal(); render(); }); }
    function changeMemberRole(u, rid) { const servers = getServers(); const server = servers[state.activeServer]; if (!server) return; if (!canManageRoles(server, state.me)) { tuxAlert('No permission', 'You do not have permission to change roles.'); return; } if (rid === 'owner' && !isOwner(server, state.me)) return; server.members[u] = rid; saveServers(servers); }
    function kickMember(u) { const servers = getServers(); const server = servers[state.activeServer]; if (!server || !canKickMembers(server, state.me)) return; tuxConfirmDelete('Kick Member', 'Kick @' + u + ' from this server?', () => { const s2 = getServers(); const srv = s2[state.activeServer]; if (!srv) return; delete srv.members[u]; saveServers(s2); closeModal(); render(); }); }
    function renameChannel(id, name) { if (!name.trim()) return; const servers = getServers(); const server = servers[state.activeServer]; if (!server || !canAddChannels(server, state.me)) { tuxAlert('No permission', 'You do not have permission to rename channels.'); return; } const c = server.channels.find(ch => ch.id === id); if (c) c.name = name.trim(); saveServers(servers); }
    function addChannel() { const servers = getServers(); const server = servers[state.activeServer]; if (!server || !canAddChannels(server, state.me)) { tuxAlert('No permission', 'You do not have permission to add channels.'); return; } tuxPrompt('New Channel', 'Channel name:', '', (name) => { if (!name || !name.trim()) return; const s2 = getServers(); const srv = s2[state.activeServer]; if (!srv) return; srv.channels.push({ id:bfUid(), name:name.trim(), type:'text' }); saveServers(s2); render(); }); }
    function deleteChannel(id) { const servers = getServers(); const server = servers[state.activeServer]; if (!server || !canAddChannels(server, state.me)) { tuxAlert('No permission', 'You do not have permission to delete channels.'); return; } tuxConfirmDelete('Delete Channel', 'Delete this channel?', () => { const s2 = getServers(); const srv = s2[state.activeServer]; if (!srv) return; srv.channels = srv.channels.filter(c => c.id !== id); saveServers(s2); if (state.activeChannel === id) state.activeChannel = srv.channels.find(c => c.type === 'text')?.id; render(); }); }
    function requestRole() { const sel = document.getElementById('role-request-select'); const rid = sel?.value; if (!rid) return; const servers = getServers(); const server = servers[state.activeServer]; if (!server) return; const role = server.roles.find(r => r.id === rid); server.roleRequests = server.roleRequests || []; if (server.roleRequests.some(r => r.username === state.me && r.roleId === rid && r.status === 'pending')) { tuxAlert('Already pending', 'You already have a pending request for this role.'); return; } server.roleRequests.push({ id:bfUid(), username:state.me, roleId:rid, roleName:role?.name||rid, status:'pending', createdAt:bfNow() }); saveServers(servers); pushNotification(server.owner, { type:'role', icon:'🛡️', title:'Role Request', body:(getUsers()[state.me]?.displayName || state.me) + ' wants ' + (role?.name||rid) + ' in ' + server.name }); tuxAlert('Request sent', 'Your role request has been sent.'); closeModal(); }
    function approveRequest(rid) { const servers = getServers(); const server = servers[state.activeServer]; if (!server) return; const req = server.roleRequests.find(r => r.id === rid); if (!req) return; server.members[req.username] = req.roleId; req.status = 'approved'; saveServers(servers); pushNotification(req.username, { type:'role', icon:'✅', title:'Role Approved', body:'You got ' + req.roleName + ' in ' + server.name }); closeModal(); render(); }
    function denyRequest(rid) { const servers = getServers(); const server = servers[state.activeServer]; if (!server) return; const req = server.roleRequests.find(r => r.id === rid); if (req) { req.status = 'denied'; pushNotification(req.username, { type:'role', icon:'❌', title:'Role Denied', body:'Your request for ' + req.roleName + ' was denied' }); } saveServers(servers); closeModal(); render(); }

    function setDraft(v) { state.draft = v; }
    function onMessageKey(e) { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMessage(); } }

    function pingAllowed(userData, key) {
        const p = userData.pingPrefs;
        if (!p) return key === 'personal';
        return p[key] !== false;
    }

    function getPingTargets(server, content, channel) {
        const users = getUsers();
        const targets = new Map();
        const hasEveryone = /@everyone\b/i.test(content);
        const hasHere = /@here\b/i.test(content);
        const hasLink = /https?:\/\/\S+/i.test(content);
        const isAnnouncement = channel && /announce/i.test(channel.name);
        const mentionedRoleIds = new Set();
        server.roles.forEach(r => {
            const idRe = new RegExp('@' + r.id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![a-z0-9_])', 'i');
            const nameRe = new RegExp('@' + r.name.replace(/[^a-z0-9]/gi, '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![a-z0-9_])', 'i');
            if (idRe.test(content) || nameRe.test(content)) mentionedRoleIds.add(r.id);
        });
        const directMentions = new Set();
        const mentionRe = /@([a-z0-9_.]+)/gi;
        let m;
        while ((m = mentionRe.exec(content))) {
            const name = m[1].toLowerCase();
            if (name === 'everyone' || name === 'here') continue;
            for (const u in users) if (u.toLowerCase() === name) { directMentions.add(u); break; }
        }
        Object.keys(server.members).forEach(u => {
            if (u === state.me) return;
            const ud = users[u]; if (!ud) return;
            const myRoleId = server.members[u];
            let reason = null;
            if (directMentions.has(u) && pingAllowed(ud, 'personal')) reason = 'personal';
            if (!reason && (hasEveryone || hasHere) && pingAllowed(ud, 'everyone')) reason = 'everyone';
            if (!reason && mentionedRoleIds.has(myRoleId) && pingAllowed(ud, 'roles')) reason = 'role';
            if (!reason && hasLink && pingAllowed(ud, 'links')) reason = 'links';
            if (!reason && isAnnouncement && pingAllowed(ud, 'updates')) reason = 'updates';
            if (reason) targets.set(u, reason);
        });
        return targets;
    }

    function sendMessage() {
        const input = document.getElementById('bf-message-input');
        if (!input) return;
        const content = (state.draft !== '' ? state.draft : input.value).trim();
        if (!content) return;
        const messages = getMessages();
        const key = state.view === 'dm' ? ('dm_' + state.activeDM) : `channel_${state.activeServer}_${state.activeChannel}`;
        if (!messages[key]) messages[key] = [];
        messages[key].push({ id:bfUid(), author:state.me, content, timestamp:bfNow() });
        saveMessages(messages);

        const users = getUsers();
        const authorName = users[state.me]?.displayName || state.me;

        if (state.view === 'dm') {
            const dms = getDMs();
            const dm = dms[state.activeDM];
            if (dm) {
                const other = dm.participants.find(p => p !== state.me);
                if (other) pushNotification(other, { type:'message', icon:'💬', title:'New DM from ' + authorName, body:content.substring(0,100) });
            }
        } else {
            const servers = getServers();
            const server = servers[state.activeServer];
            const channel = server ? server.channels.find(c => c.id === state.activeChannel) : null;
            if (server) {
                const targets = getPingTargets(server, content, channel);
                targets.forEach((reason, target) => {
                    const icon = reason === 'everyone' ? '📢' : reason === 'role' ? '🛡️' : reason === 'links' ? '🔗' : reason === 'updates' ? '📢' : '@';
                    const title = reason === 'everyone' ? (authorName + ' pinged @everyone')
                        : reason === 'role' ? (authorName + ' pinged a role you have')
                        : reason === 'links' ? (authorName + ' posted a link')
                        : reason === 'updates' ? (authorName + ' posted an update')
                        : (authorName + ' mentioned you');
                    pushNotification(target, { type:'message', icon, title, body: '#' + (channel?.name||'') + ': ' + content.substring(0,100) });
                });
            }
        }
        state.draft = '';
        state.emojiPickerOpen = false;
        state.mentionPickerOpen = false;
        render();
    }

    function sendGif(url) { const messages = getMessages(); const key = state.view === 'dm' ? ('dm_' + state.activeDM) : `channel_${state.activeServer}_${state.activeChannel}`; if (!messages[key]) messages[key] = []; messages[key].push({ id:bfUid(), author:state.me, content:'', timestamp:bfNow(), attachment:{type:'gif',url} }); saveMessages(messages); closeModal(); render(); }
    function pickImage() { const input = document.createElement('input'); input.type = 'file'; input.accept = 'image/*'; input.onchange = e => { const f = e.target.files[0]; if (!f) return; const reader = new FileReader(); reader.onload = ev => { const messages = getMessages(); const key = state.view === 'dm' ? ('dm_' + state.activeDM) : `channel_${state.activeServer}_${state.activeChannel}`; if (!messages[key]) messages[key] = []; messages[key].push({ id:bfUid(), author:state.me, content:'', timestamp:bfNow(), attachment:{type:'image',url:ev.target.result} }); saveMessages(messages); render(); }; reader.readAsDataURL(f); }; input.click(); }
    function openGifPicker() { state.modal = { type:'gifPicker' }; render(); }
    function deleteMessage(key, mid) { const messages = getMessages(); if (!messages[key]) return; const msg = messages[key].find(m => m.id === mid); if (!msg) return; const servers = getServers(); const server = servers[state.activeServer]; const isAdmin = server && canManageRoles(server, state.me); if (msg.author !== state.me && !isAdmin) { tuxAlert('Not allowed', 'You can only delete your own messages.'); return; } tuxConfirmDelete('Delete Message', 'Delete this message?', () => { const msgs = getMessages(); if (!msgs[key]) return; msgs[key] = msgs[key].filter(m => m.id !== mid); saveMessages(msgs); render(); }); }
    function toggleEmojiPicker() { state.emojiPickerOpen = !state.emojiPickerOpen; state.mentionPickerOpen = false; render(); }
    function toggleMentionPicker() { state.mentionPickerOpen = !state.mentionPickerOpen; state.emojiPickerOpen = false; render(); }
    function insertEmoji(e) { state.draft = (state.draft || '') + e; state.emojiPickerOpen = false; state.refocusInput = true; render(); }
    function insertCustomEmoji(n) { state.draft = (state.draft || '') + ` :${n}: `; state.emojiPickerOpen = false; state.refocusInput = true; render(); }
    function insertMention(text) { state.draft = (state.draft || '') + text + ' '; state.mentionPickerOpen = false; state.refocusInput = true; render(); }

    function promptCreateEmoji() { state.modal = { type:'createEmoji' }; render(); }
    function createEmoji() { const name = document.getElementById('emoji-name').value.trim().toLowerCase().replace(/\s+/g, '_'); const fileInput = document.getElementById('emoji-file'); if (!name) { tuxAlert('Missing name', 'Please enter a name for the emoji.'); return; } const finish = img => { if (!img) { tuxAlert('Missing image', 'Please upload an image file.'); return; } const emojis = getEmojis(); if (Object.values(emojis).some(e => e.name === name)) { tuxAlert('Name taken', 'An emoji with that name already exists.'); return; } const id = bfUid(); emojis[id] = { id, name, image:img, creator:state.me, createdAt:bfNow() }; saveEmojis(emojis); closeModal(); render(); }; if (fileInput?.files?.[0]) { const r = new FileReader(); r.onload = e => finish(e.target.result); r.readAsDataURL(fileInput.files[0]); } else finish(null); }
    function deleteEmoji(id) { tuxConfirmDelete('Delete Emoji', 'Delete this custom emoji?', () => { const emojis = getEmojis(); delete emojis[id]; saveEmojis(emojis); render(); }); }

    function openPingSetup() { state.modal = { type:'pingSetup' }; render(); }
    function savePingPrefs(id) {
        const opt = PING_OPTIONS.find(o => o.id === id) || PING_OPTIONS[0];
        const users = getUsers();
        const me = users[state.me];
        if (!me) return;
        me.pingPrefs = { ...opt.prefs };
        me.pingRole = opt.name;
        me.pingIcon = opt.icon;
        saveUsers(users);
        state.modal = null;
        render();
    }

    function promptAddFriend() { state.modal = { type:'addFriend' }; render(); }
    function sendFriendRequest(username) { let t = username || document.getElementById('add-friend-input')?.value?.trim(); if (!t) return; t = t.replace(/^@/, ''); const users = getUsers(); const f = findUserByUsername(t, users); if (!f) { tuxAlert('No user', 'That username does not exist.'); return; } const real = f.username; if (real === state.me) { tuxAlert('Not allowed', "You can't friend yourself."); return; } const me = users[state.me]; if (me.friends?.includes(real)) { tuxAlert('Already friends', 'You are already friends with this user.'); return; } if (!f.data.friendRequests) f.data.friendRequests = []; if (f.data.friendRequests.some(r => r.from === state.me && r.status === 'pending')) { tuxAlert('Already sent', 'You already have a pending friend request.'); return; } f.data.friendRequests.push({ from:state.me, status:'pending', at:bfNow() }); f.data.notifications = f.data.notifications || []; f.data.notifications.unshift({ id:bfUid(), type:'friend', icon:'👋', title:'Friend Request', body:(users[state.me]?.displayName || state.me) + ' wants to be your friend', timestamp:bfNow(), read:false }); saveUsers(users); tuxAlert('Sent', 'Friend request sent.'); closeModal(); render(); }
    function acceptFriend(from) { const users = getUsers(); const me = users[state.me]; const fu = users[from]; me.friendRequests = (me.friendRequests || []).map(r => r.from === from ? { ...r, status:'accepted' } : r); me.friends = me.friends || []; if (!me.friends.includes(from)) me.friends.push(from); if (fu) { fu.friends = fu.friends || []; if (!fu.friends.includes(state.me)) fu.friends.push(state.me); fu.notifications = fu.notifications || []; fu.notifications.unshift({ id:bfUid(), type:'friend', icon:'✅', title:'Friend Request Accepted', body:(me.displayName || state.me) + ' accepted your friend request', timestamp:bfNow(), read:false }); } saveUsers(users); render(); }
    function denyFriend(from) { const users = getUsers(); const me = users[state.me]; me.friendRequests = (me.friendRequests || []).map(r => r.from === from ? { ...r, status:'denied' } : r); saveUsers(users); render(); }
    function unfriend(u) { const users = getUsers(); users[state.me].friends = (users[state.me].friends || []).filter(f => f !== u); if (users[u]) users[u].friends = (users[u].friends || []).filter(f => f !== state.me); saveUsers(users); render(); }
    function blockUser(u) { tuxConfirmDelete('Block User', 'Block @' + u + '? You will no longer see their messages.', () => { const users = getUsers(); users[state.me].blocked = users[state.me].blocked || []; if (!users[state.me].blocked.includes(u)) users[state.me].blocked.push(u); users[state.me].friends = (users[state.me].friends || []).filter(f => f !== u); saveUsers(users); render(); }); }
    function unblockUser(u) { const users = getUsers(); users[state.me].blocked = (users[state.me].blocked || []).filter(b => b !== u); saveUsers(users); render(); }
    function openProfile(u) { state.view = 'profile'; state.profileTarget = u || state.me; render(); }
    function openSettings() { state.view = 'settings'; render(); }
    function setAccent(c) { const users = getUsers(); users[state.me].accentColor = c; saveUsers(users); render(); }
    function setBadge(b) { const users = getUsers(); users[state.me].badge = b; saveUsers(users); render(); }
    function uploadAvatar(input) { if (!input.files?.[0]) return; const reader = new FileReader(); reader.onload = e => { const users = getUsers(); users[state.me].avatar = e.target.result; saveUsers(users); render(); }; reader.readAsDataURL(input.files[0]); }
    function uploadBanner(input) { if (!input.files?.[0]) return; const reader = new FileReader(); reader.onload = e => { const users = getUsers(); users[state.me].banner = `url("${e.target.result}") center/cover`; saveUsers(users); render(); }; reader.readAsDataURL(input.files[0]); }
    function saveProfile() { const users = getUsers(); const me = users[state.me]; me.displayName = document.getElementById('prof-display').value.trim() || me.displayName; me.pronouns = document.getElementById('prof-pronouns').value.trim(); me.bio = document.getElementById('prof-bio').value.trim(); me.avatarEmoji = document.getElementById('prof-avatar-emoji').value.trim() || me.avatarEmoji; const av = document.getElementById('prof-avatar-url').value.trim(); me.avatar = av || me.avatar; const bn = document.getElementById('prof-banner').value.trim(); me.banner = bn || me.banner; saveUsers(users); render(); }
    function closeModal() { if (state.modal && state.modal.type === 'pingSetup') return; state.modal = null; render(); }
    function memberContextMenu(ev, username) { ev.preventDefault(); ev.stopPropagation(); const users = getUsers(); const u = users[username]; if (!u) return; const isSelf = username === state.me; const items = [{ header:true, label:u.displayName + ' (@' + username + ')' }, { action:'profile', label:'View Profile', onClick:() => openProfile(username) }]; if (!isSelf) { items.push({ action:'mention', label:'@ Ping', onClick:() => insertMention('@' + username) }); items.push({ action:'dm', label:'💬 Message', onClick:() => openDMWith(username) }); items.push({ action:'friend', label:'➕ Add Friend', onClick:() => sendFriendRequest(username) }); items.push('-'); items.push({ action:'block', label:'🚫 Block', onClick:() => blockUser(username), danger:true }); } showCtxMenu(ev.clientX, ev.clientY, items); }
    function syncUsers() { const users = getUsers(); saveUsers(users); }

    return { gateTab, doLogin, doRegister, logout, showFriends, selectServer, selectChannel, openDMWith, openCreateServer, createServer, showServerMenu, saveServerSettings, deleteServer, changeMemberRole, kickMember, renameChannel, addChannel, deleteChannel, requestRole, approveRequest, denyRequest, onMessageKey, sendMessage, sendGif, pickImage, openGifPicker, deleteMessage, toggleEmojiPicker, toggleMentionPicker, insertEmoji, insertCustomEmoji, insertMention, setDraft, promptCreateEmoji, createEmoji, deleteEmoji, promptAddFriend, sendFriendRequest, acceptFriend, denyFriend, unfriend, blockUser, unblockUser, openProfile, openSettings, setAccent, setBadge, saveProfile, uploadAvatar, uploadBanner, closeModal, memberContextMenu, showServerBrowser, joinServer, leaveServer, syncUsers, pushNotification, openPingSetup, savePingPrefs, init: () => { const saved = getSession(); if (saved && getUsers()[saved]) { state.me = saved; ensureOwnerServer(saved); const u = getUsers(); u[saved].status = 'online'; saveUsers(u); const servers = getServers(); const hq = Object.values(servers).find(s => s.name === 'Bonfire HQ' && s.members[saved]); if (hq) { state.activeServer = hq.id; const ft = hq.channels.find(c => c.type === 'text'); state.activeChannel = ft?.id; } maybeShowPingSetup(); } render(); } };
})();
