};
function applyTheme(k) { const t = THEMES[k] || THEMES.dark; const r = document.documentElement.style; r.setProperty('--bg',t.bg); r.setProperty('--surface',t.surface); r.setProperty('--border',t.border); r.setProperty('--text',t.text); r.setProperty('--muted',t.muted); r.setProperty('--primary',t.primary); r.setProperty('--accent',t.accent); localStorage.setItem('tux_theme', k); const s = document.getElementById('settings-theme-select'); if (s) s.value = k; }
