function applyCustomTheme() { const c = { name:'Custom', bg:document.getElementById('ct-bg').value, surface:document.getElementById('ct-surface').value, border:document.getElementById('ct-border').value, text:document.getElementById('ct-text').value, muted:document.getElementById('ct-muted').value, primary:document.getElementById('ct-primary').value, accent:document.getElementById('ct-accent').value }; localStorage.setItem('tux_custom_theme', JSON.stringify(c)); THEMES.custom = c; const s = document.getElementById('settings-theme-select'); if (s && !s.querySelector('option[value="custom"]')) { const o = document.createElement('option'); o.value='custom'; o.innerText='Custom'; s.appendChild(o); } applyTheme('custom'); }

