let toggles = { anim:true, clock:true, desktopClock:true, compact:false, tiles:true, dockTop:true, reduceMotion:false, highContrast:false, transparency:false, tooltips:true, ctx:true, newtab:false, popups:true, history:true, panic:true, rcDisable:false, noDevTools:false, skipOnboard:false, confirmDelete:true, versionLog:false };
