    if (el('toggle-contrast')) el('toggle-contrast').classList.toggle('on', toggles.highContrast);
    if (el('toggle-transparency')) el('toggle-transparency').classList.toggle('on', toggles.transparency);
    if (el('toggle-tooltips')) el('toggle-tooltips').classList.toggle('on', toggles.tooltips);
    if (el('toggle-ctx')) el('toggle-ctx').classList.toggle('on', toggles.ctx);
    if (el('toggle-newtab')) el('toggle-newtab').classList.toggle('on', toggles.newtab);
    if (el('toggle-popups')) el('toggle-popups').classList.toggle('on', toggles.popups);
    if (el('toggle-history')) el('toggle-history').classList.toggle('on', toggles.history);
    if (el('toggle-panic')) el('toggle-panic').classList.toggle('on', toggles.panic);
    if (el('toggle-rc-disable')) el('toggle-rc-disable').classList.toggle('on', toggles.rcDisable);
    if (el('toggle-devtools')) el('toggle-devtools').classList.toggle('on', toggles.noDevTools);
    if (el('toggle-skip-onboard')) el('toggle-skip-onboard').classList.toggle('on', toggles.skipOnboard);
    if (el('toggle-confirm-delete')) el('toggle-confirm-delete').classList.toggle('on', toggles.confirmDelete);
    if (el('toggle-version-log')) el('toggle-version-log').classList.toggle('on', toggles.versionLog);
    const clk = document.getElementById('clock'); if (clk) clk.style.display = toggles.clock ? '' : 'none';
    const dclk = document.getElementById('desktop-clock'); if (dclk) dclk.style.display = toggles.desktopClock ? '' : 'none';
    document.querySelectorAll('.tile').forEach(t => t.style.display = toggles.tiles ? '' : 'none');
    document.body.style.filter = toggles.highContrast ? 'contrast(1.3)' : '';
    document.querySelectorAll('.window').forEach(w => { w.style.backdropFilter = toggles.transparency ? 'blur(20px)' : ''; w.style.background = toggles.transparency ? 'rgba(15,15,17,0.75)' : ''; });
}
function changeLayout(v) { document.body.dataset.layout = v; localStorage.setItem('tux_layout', v); applyLayoutVisibility(v); }
function applyLayoutVisibility(v) {
    const strip = document.getElementById('browser-tab-strip');
    const toolbar = document.getElementById('browser-toolbar');
    const isBrowser = v === 'browser';
    if (strip) strip.style.display = isBrowser ? 'flex' : 'none';
    if (toolbar) toolbar.style.display = isBrowser ? 'flex' : 'none';
    if (openWindows.size === 0) openWindows.add('browser');
    const activeEl = document.querySelector('.window.open');
    const activeId = activeEl ? activeEl.id.replace('win-','') : ([...openWindows][0] || 'browser');
    if (isBrowser) {
        strip.innerHTML = '';
        openWindows.forEach(id => addBrowserTab(id));
        document.querySelectorAll('.window').forEach(w => w.classList.remove('open'));
        const w = document.getElementById('win-' + activeId);
        if (w) w.classList.add('open');
        setActiveBrowserTab(activeId);
    } else if (v === 'classic') {
        document.querySelectorAll('.window').forEach(w => w.classList.remove('open'));
        const w = document.getElementById('win-' + activeId);
        if (w) w.classList.add('open');
    } else {
        document.querySelectorAll('.window').forEach(w => {
            if (w.id === 'win-browser') w.classList.add('open');
        });
    }
}
function initLayout() {
    const v = localStorage.getItem('tux_layout') || 'default';
    document.body.dataset.layout = v;
    const s = document.getElementById('settings-layout-select'); if (s) s.value = v;
    applyLayoutVisibility(v);
}
function changeFont(v) { document.documentElement.style.setProperty('--font', `'${v}', sans-serif`); localStorage.setItem('tux_font', v); }
function initFont() { const v = localStorage.getItem('tux_font') || 'Inter'; document.documentElement.style.setProperty('--font', `'${v}', sans-serif`); const s = document.getElementById('settings-font-select'); if (s) s.value = v; }
function changeDockPos(v) { localStorage.setItem('tux_dock_pos', v); applyDockPos(); }
function applyDockPos() { const d = document.getElementById('dock'); if (!d) return; const pos = localStorage.getItem('tux_dock_pos') || 'bottom'; d.style.bottom = d.style.top = d.style.left = d.style.right = ''; d.style.transform = ''; if (pos === 'bottom') { d.style.bottom = '20px'; d.style.left = '50%'; d.style.transform = 'translateX(-50%)'; d.style.flexDirection = 'row'; } else if (pos === 'top') { d.style.top = '60px'; d.style.left = '50%'; d.style.transform = 'translateX(-50%)'; d.style.flexDirection = 'row'; } else if (pos === 'left') { d.style.left = '20px'; d.style.top = '50%'; d.style.transform = 'translateY(-50%)'; d.style.flexDirection = 'column'; } else if (pos === 'right') { d.style.right = '20px'; d.style.top = '50%'; d.style.transform = 'translateY(-50%)'; d.style.flexDirection = 'column'; } }
function changeAutoLock(v) { localStorage.setItem('tux_autolock', v); }
function toggleLockOnStart(el) {
    const current = localStorage.getItem('tux_lock_on_start') === 'true';
    const next = !current;
    localStorage.setItem('tux_lock_on_start', next);
    el.classList.toggle('on', next);
}
function initLockOnStart() {
    const current = localStorage.getItem('tux_lock_on_start') === 'true';
    const el = document.getElementById('toggle-lockstart');
    if (el) el.classList.toggle('on', current);
}
function initAutoLock() { const v = localStorage.getItem('tux_autolock') || '0'; const s = document.getElementById('settings-autolock'); if (s) s.value = v; if (v !== '0') { let t; document.addEventListener('mousemove', () => { clearTimeout(t); t = setTimeout(lockSystem, parseInt(v) * 60000); }); } }
