let unpinned = { menubar:[], dock:[], tiles:[] };
try { const s = JSON.parse(localStorage.getItem('tux_unpinned')); if (s) unpinned = { menubar:[], dock:[], tiles:[], ...s }; } catch(e) {}
function saveUnpins() { localStorage.setItem('tux_unpinned', JSON.stringify(unpinned)); }
function unpinItem(type, id) { if (!unpinned[type].includes(id)) { unpinned[type].push(id); saveUnpins(); applyUnpins(); } }
function pinItem(type, id) { unpinned[type] = unpinned[type].filter(x => x !== id); saveUnpins(); applyUnpins(); }
function restoreAllPins() { unpinned = { menubar:[], dock:[], tiles:[] }; saveUnpins(); applyUnpins(); }
function applyUnpins() { document.querySelectorAll('.menu-bar [data-app]').forEach(el => { el.style.display = unpinned.menubar.includes(el.dataset.app) ? 'none' : ''; }); document.querySelectorAll('.dock-icon[data-app]').forEach(el => { el.style.display = unpinned.dock.includes(el.dataset.app) ? 'none' : ''; }); document.querySelectorAll('.tile[data-tile-id]').forEach(el => { el.style.display = unpinned.tiles.includes(el.dataset.tileId) ? 'none' : ''; }); }

const tooltipEl = document.getElementById('global-tooltip'); let tooltipTimer = null;
document.addEventListener('mouseover', e => { if (!toggles.tooltips) return; const t = e.target.closest('[data-tooltip]'); if (!t) return; clearTimeout(tooltipTimer); tooltipTimer = setTimeout(() => { tooltipEl.textContent = t.dataset.tooltip; const r = t.getBoundingClientRect(); tooltipEl.style.left = (r.left + r.width/2) + 'px'; tooltipEl.style.top = (t.closest('.dock') ? (r.top - 34) : (r.bottom + 8)) + 'px'; tooltipEl.classList.add('visible'); }, 250); });
document.addEventListener('mouseout', e => { if (e.target.closest('[data-tooltip]')) { clearTimeout(tooltipTimer); tooltipEl.classList.remove('visible'); } });
document.addEventListener('mousedown', () => { clearTimeout(tooltipTimer); tooltipEl.classList.remove('visible'); });

function showCtxMenu(x, y, items) { if (!toggles.ctx) return; const menu = document.getElementById('context-menu'); menu.innerHTML = items.map(it => { if (it === '-') return '
'; if (it.header) return `
${it.label}`; return `
${it.label}`; }).join(''); menu.querySelectorAll('.ctx-item').forEach(el => { el.onclick = (ev) => { ev.stopPropagation(); const it = items.find(i => i.action === el.dataset.action && !i.header); if (it && it.onClick) it.onClick(); hideCtxMenu(); }; }); menu.style.left = x + 'px'; menu.style.top = y + 'px'; menu.classList.add('active'); requestAnimationFrame(() => { const r = menu.getBoundingClientRect(); if (r.right > window.innerWidth - 8) menu.style.left = (window.innerWidth - r.width - 8) + 'px'; if (r.bottom > window.innerHeight - 8) menu.style.top = (window.innerHeight - r.height - 8) + 'px'; }); }
function hideCtxMenu() { document.getElementById('context-menu').classList.remove('active'); }
document.addEventListener('click', hideCtxMenu);
document.addEventListener('contextmenu', e => {
    if (toggles.rcDisable) { e.preventDefault(); return; }
    e.preventDefault();
    const t = e.target;
    if (t.closest('.menu-bar')) { const mi = t.closest('.menu-item[data-app]'); if (mi) { const a = mi.dataset.app; showCtxMenu(e.clientX, e.clientY, [{header:true,label:mi.dataset.tooltip||mi.textContent.trim()},{action:'open',label:'Open',onClick:()=>openWindow(a)},{action:'unpin',label:'Unpin from Taskbar',onClick:()=>unpinItem('menubar',a)},'-',{action:'settings',label:'Settings',onClick:()=>openWindow('settings')},{action:'restore',label:'Restore All Pins',onClick:restoreAllPins},'-',{action:'lock',label:'Lock Screen',onClick:lockSystem}]); return; } showCtxMenu(e.clientX, e.clientY, [{header:true,label:'Taskbar'},{action:'settings',label:'Settings',onClick:()=>openWindow('settings')},{action:'restore',label:'Restore All Pins',onClick:restoreAllPins},'-',{action:'lock',label:'Lock Screen',onClick:lockSystem}]); return; }
    const di = t.closest('.dock-icon[data-app]'); if (di) { const a = di.dataset.app; showCtxMenu(e.clientX, e.clientY, [{header:true,label:di.dataset.tooltip||a},{action:'open',label:'Open',onClick:()=>openWindow(a)},{action:'unpin',label:'Unpin from Dock',onClick:()=>unpinItem('dock',a)},'-',{action:'pin-taskbar',label:'Pin to Taskbar',onClick:()=>pinItem('menubar',a)},{action:'pin-desktop',label:'Add to Desktop',onClick:()=>pinItem('tiles',a)}]); return; }
    const sa = t.closest('.start-app[data-app]'); if (sa) { const a = sa.dataset.app; showCtxMenu(e.clientX, e.clientY, [{header:true,label:sa.dataset.tooltip||'App'},{action:'open',label:'Open',onClick:()=>launchStartApp(a)},'-',{action:'pin-taskbar',label:'Pin to Taskbar',onClick:()=>pinItem('menubar',a)},{action:'pin-dock',label:'Pin to Dock',onClick:()=>pinItem('dock',a)},{action:'pin-desktop',label:'Add to Desktop',onClick:()=>pinItem('tiles',a)}]); return; }
    const ti = t.closest('.tile[data-tile-id]'); if (ti) { const a = ti.dataset.tileId; const l = ti.querySelector('.tile-label')?.textContent || a; showCtxMenu(e.clientX, e.clientY, [{header:true,label:l},{action:'open',label:'Open',onClick:()=>openWindow(a)},{action:'unpin',label:'Remove from Desktop',onClick:()=>unpinItem('tiles',a)},{action:'reset',label:'Reset Position',onClick:()=>{const s=JSON.parse(localStorage.getItem('tux_tile_positions'))||{}; delete s[a]; localStorage.setItem('tux_tile_positions',JSON.stringify(s)); ti.style.left='24px'; ti.style.top='24px';}},'-',{action:'pin-dock',label:'Pin to Dock',onClick:()=>pinItem('dock',a)}]); return; }
    const wt = t.closest('.win-titlebar'); if (wt) { const w = wt.closest('.window'); const wid = w.id.replace('win-',''); showCtxMenu(e.clientX, e.clientY, [{header:true,label:'Window'},{action:'min',label:'Minimize',onClick:()=>minimizeWindow(wid)},{action:'max',label:'Maximize',onClick:()=>toggleMaximize('win-'+wid)},'-',{action:'close',label:'Close',onClick:()=>closeWindow(wid),danger:true}]); return; }
    if (t.closest('.desktop')) { showCtxMenu(e.clientX, e.clientY, [{header:true,label:'Desktop'},{action:'wallpaper',label:'Change Wallpaper',onClick:()=>{openWindow('settings'); setTimeout(()=>{const n=[...document.querySelectorAll('.settings-nav-item')].find(x=>x.textContent.includes('Wallpaper')); if(n)switchSettings('wallpaper',n);},100);}},{action:'settings',label:'Settings',onClick:()=>openWindow('settings')},{action:'restore-tiles',label:'Restore All Tiles',onClick:()=>{unpinned.tiles=[];saveUnpins();applyUnpins();}},'-',{action:'lock',label:'Lock Screen',onClick:lockSystem}]); return; }
    showCtxMenu(e.clientX, e.clientY, [{action:'settings',label:'Settings',onClick:()=>openWindow('settings')},{action:'lock',label:'Lock Screen',onClick:lockSystem}]);
});

const DEFAULT_TILE_POSITIONS = { browser:{x:24,y:20}, games:{x:24,y:100}, movies:{x:24,y:180}, bonfire:{x:24,y:260}, ai:{x:130,y:20}, music:{x:130,y:100}, calculator:{x:130,y:180}, notes:{x:130,y:260}, clock:{x:236,y:20}, calendar:{x:236,y:100}, changelog:{x:236,y:180}, settings:{x:236,y:260} };
let tileDrag = null, lastTileDragEnd = 0;
function initTiles() { let stored = {}; try { stored = JSON.parse(localStorage.getItem('tux_tile_positions')) || {}; } catch(e) {} document.querySelectorAll('.tile[data-tile-id]').forEach(tile => { const id = tile.dataset.tileId; const pos = stored[id] || DEFAULT_TILE_POSITIONS[id] || {x:24,y:24}; tile.style.left = pos.x + 'px'; tile.style.top = pos.y + 'px'; tile.addEventListener('mousedown', e => { if (e.button !== 0) return; e.preventDefault(); tileDrag = { tile, id, startX:e.clientX, startY:e.clientY, origX:tile.offsetLeft, origY:tile.offsetTop, moved:false }; document.addEventListener('mousemove', onTileDrag); document.addEventListener('mouseup', endTileDrag); }); }); }
function onTileDrag(e) { if (!tileDrag) return; const dx = e.clientX - tileDrag.startX, dy = e.clientY - tileDrag.startY; if (Math.abs(dx) > 5 || Math.abs(dy) > 5) tileDrag.moved = true; if (!tileDrag.moved) return; tileDrag.tile.style.left = (tileDrag.origX + dx) + 'px'; tileDrag.tile.style.top = (tileDrag.origY + dy) + 'px'; }
function endTileDrag() { if (!tileDrag) return; if (tileDrag.moved) { lastTileDragEnd = Date.now(); let s = {}; try { s = JSON.parse(localStorage.getItem('tux_tile_positions')) || {}; } catch(e) {} s[tileDrag.id] = {x:tileDrag.tile.offsetLeft, y:tileDrag.tile.offsetTop}; localStorage.setItem('tux_tile_positions', JSON.stringify(s)); } tileDrag = null; document.removeEventListener('mousemove', onTileDrag); document.removeEventListener('mouseup', endTileDrag); }

function nextObStep(s) { document.querySelectorAll('.ob-step').forEach(x => x.classList.remove('active')); document.getElementById('ob-step-'+s).classList.add('active'); }
function finishOnboarding() { const u = document.getElementById('ob-username').value.trim() || 'User'; const p = document.getElementById('ob-password').value.trim() || 'verity'; localStorage.setItem('tux_onboarded','true'); localStorage.setItem('tux_username',u); localStorage.setItem('tux_password',p); document.getElementById('onboarding').classList.add('hidden'); setupLockScreen(u); document.getElementById('lock-screen').classList.remove('unlocked'); document.getElementById('lock-screen').classList.add('locked'); }
function setupLockScreen(u) { document.getElementById('lock-name').innerText = u; document.getElementById('lock-avatar').innerText = u.charAt(0).toUpperCase(); }
function updateLockClock() { const n = new Date(); document.getElementById('lock-time').innerText = n.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}); document.getElementById('lock-date').innerText = n.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}); }
setInterval(updateLockClock, 1000); updateLockClock();
function unlockSystem() { const p = document.getElementById('lock-password').value; const s = localStorage.getItem('tux_password') || 'verity'; const g = document.getElementById('lock-input-group'); const e = document.getElementById('lock-error'); if (p === s || p === '') { document.getElementById('lock-screen').classList.remove('locked'); document.getElementById('lock-screen').classList.add('unlocked'); document.getElementById('lock-password').value = ''; } else { g.classList.add('shake'); e.style.opacity = '1'; setTimeout(() => { g.classList.remove('shake'); e.style.opacity = '0'; }, 2000); } }
function lockSystem() { document.getElementById('lock-screen').classList.remove('unlocked'); document.getElementById('lock-screen').classList.add('locked'); document.getElementById('lock-password').value = ''; setTimeout(() => document.getElementById('lock-password').focus(), 500); }

