let browserTabCounter = 0;
const browserTabs = new Map();

function createNewTab(url = null) {
    browserTabCounter++;
    const tabId = 'tab-' + browserTabCounter;

    const tabEl = document.createElement('div');
    tabEl.className = 'b-tab';
    tabEl.id = tabId;
    tabEl.innerHTML = 'New Tab×';
    tabEl.onclick = function() { switchToTab(tabId); };

    const strip = document.getElementById('browser-tabs');
    const addBtn = strip.querySelector('.tab-add-btn');
    if (addBtn) strip.insertBefore(tabEl, addBtn); else strip.appendChild(tabEl);

    const iframe = document.createElement('iframe');
    iframe.className = 'tab-iframe';
    iframe.id = 'iframe-' + tabId;
    iframe.src = 'about:blank';
    iframe.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox allow-modals allow-downloads allow-storage-access-by-user-activation');
    document.getElementById('browser-body').appendChild(iframe);

    browserTabs.set(tabId, { iframe: iframe, tabEl: tabEl, url: null, title: 'New Tab' });

    if (url) loadUrlInTab(tabId, url);
    else {
        switchToTab(tabId);
        const urlInput = document.getElementById('url-input');
        if (urlInput) { urlInput.value = ''; setTimeout(function() { urlInput.focus(); }, 50); }
    }
    return tabId;
}

function switchToTab(tabId) {
    // 1. Wipe active state from EVERY tab and EVERY iframe, guaranteed
    document.querySelectorAll('.b-tab').forEach(function(t) { t.classList.remove('active'); });
    document.querySelectorAll('.tab-iframe').forEach(function(f) { f.classList.remove('active'); });

    const homeScreen = document.getElementById('home-screen');
    const urlInput = document.getElementById('url-input');

    // 2. Home tab → show the home screen
    if (tabId === 'tab-home') {
        homeScreen.style.display = 'flex';
        const ht = document.getElementById('tab-home');
        if (ht) ht.classList.add('active');
        if (urlInput) urlInput.value = '';
        return;
    }

    const tab = browserTabs.get(tabId);
    if (!tab) return;

    // 3. Empty tab (no URL yet) → also show the home screen, no white flash
    if (!tab.url) {
        homeScreen.style.display = 'flex';
        tab.tabEl.classList.add('active');
        if (urlInput) urlInput.value = '';
        return;
    }

    // 4. Tab with a loaded URL → hide home, show this tab's iframe
    homeScreen.style.display = 'none';
    tab.iframe.classList.add('active');
    tab.tabEl.classList.add('active');
    if (urlInput) urlInput.value = tab.url;
}

function closeTab(tabId) {
    if (tabId === 'tab-home') return;
    const tab = browserTabs.get(tabId);
    if (!tab) return;
    const wasActive = tab.tabEl.classList.contains('active');
    tab.tabEl.remove();
    tab.iframe.remove();
    browserTabs.delete(tabId);
    if (wasActive) {
        const remaining = Array.from(browserTabs.keys());
        if (remaining.length) switchToTab(remaining[remaining.length - 1]);
        else switchToTab('tab-home');
    }
}


function loadUrlInTab(tabId, url) {
    const tab = browserTabs.get(tabId);
    if (!tab) return;
    if (typeof __uv$config === 'undefined' || !__uv$config) {
        tab.iframe.srcdoc = '
Proxy not ready
Ultraviolet didn\'t load. Make sure you are on http://localhost:8081, not file://. Check the console.';
        return;
    }
    const proxiedUrl = __uv$config.prefix + __uv$config.encodeUrl(url);
    tab.iframe.src = proxiedUrl;
    tab.url = url;
    let label = url.replace(/^https?:\/\//i, '').replace(/^www\./i, '');
    if (label.length > 22) label = label.substring(0, 22) + '…';
    tab.title = label;
    const titleEl = tab.tabEl.querySelector('.b-tab-title');
    if (titleEl) titleEl.textContent = label;
    switchToTab(tabId);
}

function loadBrowserUrl() {
    const urlInput = document.getElementById('url-input');
    const homeInput = document.getElementById('home-input');
    const input = (urlInput && urlInput.value.trim()) || (homeInput && homeInput.value.trim());
    if (!input) return;

    let url = input;
    if (!/^https?:\/\//i.test(url) && !/^[\w-]+\.[\w.-]+/.test(url)) {
        const b = currentSearchEngine === 'custom' ? customSearchUrl : SEARCH_ENGINES[currentSearchEngine];
        url = b.includes('%s') ? b.replace('%s', encodeURIComponent(input)) : b + encodeURIComponent(input);
    } else if (!/^https?:\/\//i.test(url)) {
        url = 'https://' + url;
    }

    const activeTab = document.querySelector('.b-tab.active');
    const targetTabId = (activeTab && activeTab.id !== 'tab-home') ? activeTab.id : null;
    if (targetTabId) {
        loadUrlInTab(targetTabId, url);
    } else {
        createNewTab(url);
    }

    if (homeInput) homeInput.value = '';
    if (urlInput) urlInput.value = url;

    if (toggles.history) {
        const h = JSON.parse(localStorage.getItem('tux_history') || '[]');
        h.unshift({ url, ts: Date.now() });
        localStorage.setItem('tux_history', JSON.stringify(h.slice(0, 100)));
    }
}
function closeWebTab() {
    const activeTab = document.querySelector('.b-tab.active');
    if (activeTab && activeTab.id !== 'tab-home') closeTab(activeTab.id);
}
function switchBrowserTab(t) { switchToTab(t === 'home' ? 'tab-home' : t); }
const openWindows = new Set(['browser']); let zIndexCounter = 1000;
function openWindow(id) {
    if (Date.now() - lastTileDragEnd < 150) return;
    const w = document.getElementById('win-' + id);
    if (!w) return;
    const layout = document.body.dataset.layout;
    if (layout === 'browser' || layout === 'classic') {
        document.querySelectorAll('.window').forEach(x => x.classList.remove('open'));
        w.classList.add('open');
        openWindows.add(id);
        updateDock();
        if (layout === 'browser') {
            if (!document.querySelector(`.browser-tab[data-app="${id}"]`)) addBrowserTab(id);
            setActiveBrowserTab(id);
        }
        if (id === 'bonfire') BONFIRE.init();
        if (id === 'calendar') renderCalendar();
        if (id === 'changelog') renderChangelog();
        return;
    }
    w.classList.add('open'); w.style.zIndex = ++zIndexCounter;
    openWindows.add(id); updateDock();
    if (id === 'bonfire') BONFIRE.init();
    if (id === 'calendar') renderCalendar();
    if (id === 'changelog') renderChangelog();
}
function addBrowserTab(id) {
    const labels = { browser:'Browser', games:'Games', movies:'Movies', bonfire:'Bonfire', ai:'AI Hub', music:'Music', calculator:'Calculator', notes:'Notes', clock:'Clock', calendar:'Calendar', changelog:'Changelog', settings:'Settings' };
    const strip = document.getElementById('browser-tab-strip');
    if (!strip) return;
    if (strip.querySelector(`.browser-tab[data-app="${id}"]`)) return;
    const tab = document.createElement('div');
    tab.className = 'browser-tab';
    tab.dataset.app = id;
    tab.innerHTML = `${labels[id] || id}×`;
    tab.onclick = () => openWindow(id);
    strip.appendChild(tab);
}
function setActiveBrowserTab(id) {
    document.querySelectorAll('.browser-tab').forEach(t => t.classList.toggle('active', t.dataset.app === id));
    const ob = document.getElementById('browser-omnibox');
    if (ob) ob.value = '';
}
function closeBrowserTab(id) {
    const tab = document.querySelector(`.browser-tab[data-app="${id}"]`);
    if (tab) tab.remove();
    const w = document.getElementById('win-' + id);
    if (w) w.classList.remove('open');
    openWindows.delete(id);
    const remaining = document.querySelectorAll('.browser-tab');
    if (remaining.length) remaining[remaining.length-1].click();
    updateDock();
}
function browserNavigate(input) {
    if (!input) return;
    const activeTab = document.querySelector('.browser-tab.active');
    const activeId = activeTab ? activeTab.dataset.app : 'browser';
    if (activeId === 'browser') {
        const urlInput = document.getElementById('url-input');
        const homeInput = document.getElementById('home-input');
        if (urlInput) urlInput.value = input;
        if (homeInput) homeInput.value = input;
        loadBrowserUrl();
    } else {
        const w = document.getElementById('win-' + activeId);
        if (w) {
            const inp = w.querySelector('input[type="text"]');
            if (inp) { inp.value = input; inp.focus(); }
        }
    }
    document.getElementById('browser-omnibox').value = '';
}
function browserNav(action) {
    if (action === 'reload') {
        const activeInnerTab = document.querySelector('.b-tab.active');
        if (activeInnerTab && activeInnerTab.id !== 'tab-home') {
            const tab = browserTabs.get(activeInnerTab.id);
            if (tab && tab.iframe && tab.iframe.src) tab.iframe.src = tab.iframe.src;
        }
    }
}
function closeWindow(id) { const w = document.getElementById('win-'+id); if (w) { w.classList.remove('open'); openWindows.delete(id); updateDock(); } }
function minimizeWindow(id) { const w = document.getElementById('win-'+id); if (w) w.classList.remove('open'); }
