const GROQ_KEY = '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';
let aiChats = JSON.parse(localStorage.getItem('tux_ai_chats')) || []; let currentChatId = null;
function deleteChat(id) { if (aiChats.length <= 1) { tuxAlert('Cannot delete', "You can't delete your only chat."); return; } tuxConfirmDelete('Delete Chat', 'Delete this chat?', () => { aiChats = aiChats.filter(c => c.id !== id); if (currentChatId === id) currentChatId = aiChats[aiChats.length - 1].id; saveChats(); renderChatList(); renderMessages(); }); }
function initAI() { if (aiChats.length === 0) createNewChat(); else { currentChatId = aiChats[aiChats.length-1].id; renderChatList(); renderMessages(); } }
function saveChats() { localStorage.setItem('tux_ai_chats', JSON.stringify(aiChats)); }
function createNewChat() { const n = { id:Date.now().toString(), title:'New Chat', messages:[{ role:'bot', text:'New chat started. How can I help you?' }] }; aiChats.push(n); currentChatId = n.id; saveChats(); renderChatList(); renderMessages(); }
function renderChatList() {
    const l = document.getElementById('ai-chat-list');
    if (!l) return;
    l.innerHTML = [...aiChats].reverse().map(c =>
        `

            ${c.title}
            ×
        `
    ).join('');
}
function selectChat(id) { currentChatId = id; renderChatList(); renderMessages(); }
function renderMessages() { const c = aiChats.find(x => x.id === currentChatId); const p = document.getElementById('ai-chat'); if (!c || !p) return; p.innerHTML = c.messages.map(m => `

${m.role==='user'?'U':'AI'}
${m.text}`).join(''); p.scrollTop = p.scrollHeight; }
async function sendAI() {
    const i = document.getElementById('ai-input');
    const prompt = i.value.trim();
    if (!prompt) return;
    const c = aiChats.find(x => x.id === currentChatId);
    if (c.title === 'New Chat') c.title = prompt.substring(0, 15);
    c.messages.push({ role: 'user', text: prompt });
    i.value = '';
    renderChatList();
    renderMessages();
    const loadIdx = c.messages.length;
    c.messages.push({ role: 'bot', text: '...' });
    renderMessages();
    let reply = null;
    if (GROQ_KEY.includes('PASTE_YOUR')) {
        c.messages[loadIdx].text = '⚙️ AI requires a key. Get a free one at console.groq.com/keys, then paste it into GROQ_KEY near the top of the AI section in tux.html.';
        saveChats();
        renderMessages();
        return;
    }
    try {
        const res = await fetch('https://api.groq.com/openai/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + GROQ_KEY },
            body: JSON.stringify({ model: 'openai/gpt-oss-120b', messages: [{ role: 'user', content: prompt }] })
        });
        if (res.ok) {
            const data = await res.json();
            reply = data.choices?.[0]?.message?.content;
        } else {
            console.error('Groq HTTP', res.status, await res.text());
        }
    } catch (e) {
        console.error('Groq failed:', e);
    }
    c.messages[loadIdx].text = reply || 'AI offline.';
    saveChats();
    renderMessages();
}

function switchSettings(id, el) { document.querySelectorAll('.settings-section').forEach(s => s.classList.remove('active')); document.getElementById('settings-'+id).classList.add('active'); document.querySelectorAll('.settings-nav-item').forEach(n => n.classList.remove('active')); el.classList.add('active'); }

function updateClocks() {
    const n = new Date();
    const time = n.toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' });
    const date = n.toLocaleDateString('en-US', { weekday:'long', month:'long', day:'numeric' });
    const shortDate = n.toLocaleDateString('en-US', { weekday:'short', month:'short', day:'numeric' });
    const c = document.getElementById('clock'); if (c) c.innerText = time;
    const dt = document.getElementById('dc-time'); if (dt) dt.textContent = time;
    const dd = document.getElementById('dc-date'); if (dd) dd.textContent = shortDate;
    const ht = document.getElementById('home-clock-time'); if (ht) ht.textContent = time;
    const hd = document.getElementById('home-clock-date'); if (hd) hd.textContent = date;
}
setInterval(updateClocks, 1000); updateClocks();

document.addEventListener('keydown', e => {
    if (toggles.panic && e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'x') window.location.href = 'https://classroom.google.com';
    if (e.ctrlKey && e.altKey && e.key.toLowerCase() === 'l') lockSystem();
    if (toggles.noDevTools && (e.key === 'F12' || (e.ctrlKey && e.shiftKey && (e.key === 'I' || e.key === 'J' || e.key === 'C')))) { e.preventDefault(); return false; }
});

function buildClassicWindowButtons() {
    document.querySelectorAll('.win-titlebar').forEach(tb => {
        if (tb.querySelector('.classic-win-btns')) return;
        const win = tb.closest('.window'); if (!win) return;
        const id = win.id.replace('win-','');
        const box = document.createElement('div');
        box.className = 'classic-win-btns';
        box.innerHTML = `_□×`;
        tb.appendChild(box);
    });
}

async function searchAudius() {
    const query = document.getElementById('audius-search').value.trim();
    if (!query) return;
    const resultsEl = document.getElementById('audius-results');
    resultsEl.innerHTML = '
Searching...';
    try {
        const res = await fetch(`https://api.audius.co/v1/tracks/search?query=${encodeURIComponent(query)}&app_name=TUX_OS`);
        const data = await res.json();
        if (!data.data || data.data.length === 0) {
            resultsEl.innerHTML = '
No results found.';
            return;
        }
        resultsEl.innerHTML = data.data.map(track => `
            <div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:14px;cursor:pointer;" onclick="playAudiusTrack('${track.id}', '${track.title.replace(/'/g, "\\'")}', '${track.user.name.replace(/'/g, "\\'")}', this)">

${track.title}

${track.user.name}

        `).join('');
    } catch (e) {
        console.error('Audius search failed:', e);
        resultsEl.innerHTML = '
Search failed. Check console.';
    }
}

async function playAudiusTrack(id, title, artist, el) {
    const audio = document.getElementById('audius-audio');
    try {
        const streamRes = await fetch(`https://api.audius.co/v1/tracks/${id}/stream?app_name=TUX_OS`, { redirect: 'follow' });
        audio.src = streamRes.url;
        audio.style.display = 'block';
        audio.play();
        audio.title = `${title} — ${artist}`;
    } catch (e) {
        console.error('Playback failed:', e);
    }
}

function init() {
    initLayout();
    initFont();
    applyDockPos();
    applyTheme(localStorage.getItem('tux_theme') || 'dark');
    initThemes();
    initCustomUI();
    applyToggles();
    initTiles();
    applyUnpins();
    renderGames();
    initMovies();
    initWallpaper();
    initNotes();
    initCloak();
    initExt();
    updateDock();
    initSearchEngine();
    initTextCloak();
    initAI();
    initAutoLock();
    initLockOnStart();
    renderCalendar();
    renderChangelog();
    updateNotifUI();
    buildClassicWindowButtons();
    const lockOnStart = localStorage.getItem('tux_lock_on_start') === 'true';
    const o = localStorage.getItem('tux_onboarded');
    if (!o) {
        document.getElementById('onboarding').classList.remove('hidden');
        document.getElementById('lock-screen').classList.remove('locked');
        document.getElementById('lock-screen').classList.add('unlocked');
    } else {
        const u = localStorage.getItem('tux_username') || 'User';
        setupLockScreen(u);
        document.getElementById('onboarding').classList.add('hidden');
        if (lockOnStart) {
            document.getElementById('lock-screen').classList.remove('unlocked');
            document.getElementById('lock-screen').classList.add('locked');
            setTimeout(() => document.getElementById('lock-password').focus(), 500);
        } else {
            document.getElementById('lock-screen').classList.remove('locked');
            document.getElementById('lock-screen').classList.add('unlocked');
        }
    }
}
init();
